toolArgs.file_text:
@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Project Board</h1>

@if (isLoading)
{
    <p class="loading">Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <p class="error">@errorMessage</p>
}
else
{
    <!-- Stats Bar -->
    <div class="stats-bar">
        <span class="stat">Total: @filteredTasks.Count</span>
        <span class="stat">To Do: @TodoTasks.Count</span>
        <span class="stat">In Progress: @InProgressTasks.Count</span>
        <span class="stat">Done: @DoneTasks.Count</span>
        <span class="stat stat-overdue">Overdue: @OverdueCount</span>
    </div>

    <!-- Search Bar -->
    <div class="search-bar">
        <input type="text" placeholder="Search tasks by title..." @bind="searchTerm" @bind:event="oninput" />
    </div>

    <!-- Columns -->
    <div class="board-columns">
        @foreach (var column in columns)
        {
            var columnTasks = GetTasksForColumn(column);
            var colIndex = Array.IndexOf(columns, column);
            <div class="kanban-column">
                <div class="column-header">
                    <h3>@column (@columnTasks.Count)</h3>
                </div>
                <div class="column-body">
                    @foreach (var task in columnTasks)
                    {
                        var capturedIndex = colIndex;
                        var capturedTask = task;
                        <TaskCard Task="capturedTask"
                                  CanMoveLeft="capturedIndex > 0"
                                  CanMoveRight="capturedIndex < columns.Length - 1"
                                  OnMoveLeft="() => MoveTask(capturedTask, columns[capturedIndex - 1])"
                                  OnMoveRight="() => MoveTask(capturedTask, columns[capturedIndex + 1])" />
                    }
                </div>
                <div class="column-footer">
                    @if (showAddForm == column)
                    {
                        <AddTaskForm Status="@column"
                                     OnTaskCreated="OnTaskCreated"
                                     OnCancel="() => showAddForm = null" />
                    }
                    else
                    {
                        <button class="btn-add" @onclick="() => showAddForm = column">+ Add Task</button>
                    }
                </div>
            </div>
        }
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private bool isLoading = true;
    private string? errorMessage;
    private string searchTerm = "";
    private string? showAddForm;

    private static readonly string[] columns = { "To Do", "In Progress", "Done" };

    private List<TaskItem> filteredTasks => string.IsNullOrWhiteSpace(searchTerm)
        ? allTasks
        : allTasks.Where(t => t.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase)).ToList();

    private List<TaskItem> TodoTasks => GetTasksForColumn("To Do");
    private List<TaskItem> InProgressTasks => GetTasksForColumn("In Progress");
    private List<TaskItem> DoneTasks => GetTasksForColumn("Done");
    private int OverdueCount => filteredTasks.Count(t => t.DueDate < DateTime.Today);

    private List<TaskItem> GetTasksForColumn(string status) =>
        filteredTasks.Where(t => t.Status == status).ToList();

    protected override async System.Threading.Tasks.Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async System.Threading.Tasks.Task MoveTask(TaskItem task, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = allTasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
            {
                allTasks[index] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private void OnTaskCreated(TaskItem task)
    {
        allTasks.Add(task);
        showAddForm = null;
    }
}

