+    private List<TaskItem> filteredTasks => string.IsNullOrWhiteSpace(searchTerm)
+        ? allTasks
+        : allTasks.Where(t => t.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase)).ToList();
+
+    private List<TaskItem> TodoTasks => GetTasksForColumn("To Do");
+    private List<TaskItem> InProgressTasks => GetTasksForColumn("In Progress");
+    private List<TaskItem> DoneTasks => GetTasksForColumn("Done");
+    private int OverdueCount => filteredTasks.Count(t => t.DueDate < DateTime.Today);
+
+    private List<TaskItem> GetTasksForColumn(string status) =>
+        filteredTasks.Where(t => t.Status == status).ToList();
+
+    protected override async System.Threading.Tasks.Task OnInitializedAsync()
+    {
+        try
+        {
+            allTasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to load tasks: {ex.Message}";
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private async System.Threading.Tasks.Task MoveTask(TaskItem task, string newStatus)
+    {
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
+            var index = allTasks.FindIndex(t => t.Id == task.Id);
+            if (index >= 0)
+            {
+                allTasks[index] = task with { Status = newStatus };
+            }
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to move task: {ex.Message}";
+        }
