+        <span class="stat">To Do: @TodoTasks.Count</span>
+        <span class="stat">In Progress: @InProgressTasks.Count</span>
+        <span class="stat">Done: @DoneTasks.Count</span>
+        <span class="stat stat-overdue">Overdue: @OverdueCount</span>
+    </div>
+
+    <!-- Search Bar -->
+    <div class="search-bar">
+        <input type="text" placeholder="Search tasks by title..." @bind="searchTerm" @bind:event="oninput" />
+    </div>
+
+    <!-- Columns -->
+    <div class="board-columns">
+        @foreach (var column in columns)
+        {
+            var columnTasks = GetTasksForColumn(column);
+            var colIndex = Array.IndexOf(columns, column);
+            <div class="kanban-column">
+                <div class="column-header">
+                    <h3>@column (@columnTasks.Count)</h3>
+                </div>
+                <div class="column-body">
+                    @foreach (var task in columnTasks)
+                    {
+                        var capturedIndex = colIndex;
+                        var capturedTask = task;
+                        <TaskCard Task="capturedTask"
+                                  CanMoveLeft="capturedIndex > 0"
+                                  CanMoveRight="capturedIndex < columns.Length - 1"
+                                  OnMoveLeft="() => MoveTask(capturedTask, columns[capturedIndex - 1])"
+                                  OnMoveRight="() => MoveTask(capturedTask, columns[capturedIndex + 1])" />
+                    }
+                </div>
+                <div class="column-footer">
+                    @if (showAddForm == column)
+                    {
+                        <AddTaskForm Status="@column"
+                                     OnTaskCreated="OnTaskCreated"
+                                     OnCancel="() => showAddForm = null" />
+                    }
+                    else
+                    {
+                        <button class="btn-add" @onclick="() => showAddForm = column">+ Add Task</button>
+                    }
+                </div>
+            </div>
+        }
+    </div>
+}
