toolArgs.file_text:
.stats-bar {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.stat {
    font-weight: 600;
    padding: 0.25rem 0.75rem;
    background: #e9ecef;
    border-radius: 4px;
}

.stat-overdue {
    background: #fee2e2;
    color: #dc2626;
}

.search-bar {
    margin-bottom: 1rem;
}

.search-bar input {
    width: 100%;
    max-width: 400px;
    padding: 0.5rem 1rem;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    font-size: 1rem;
}

.board-columns {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

.kanban-column {
    flex: 1;
    background: #f1f3f5;
    border-radius: 8px;
    padding: 1rem;
    min-width: 250px;
    display: flex;
    flex-direction: column;
}

.column-header h3 {
    margin: 0 0 0.75rem;
    font-size: 1.1rem;
}

.column-body {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    min-height: 100px;
}

.column-footer {
    margin-top: 1rem;
}

.btn-add {
    width: 100%;
    padding: 0.5rem;
    background: transparent;
    border: 2px dashed #adb5bd;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.9rem;
    color: #495057;
}

.btn-add:hover {
    border-color: #495057;
    background: #e9ecef;
}

.loading {
    text-align: center;
    color: #6c757d;
    padding: 2rem;
}

.error {
    color: #dc2626;
    background: #fee2e2;
    padding: 1rem;
    border-radius: 6px;
}

